      /* (1773) with_recursive_tail ::= */ yytestcase(yyruleno==1773);
      /* (1779) with_cte_column_tail ::= */ yytestcase(yyruleno==1779);
      /* (1786) with_cte_body_nested ::= */ yytestcase(yyruleno==1786);
      /* (1806) table_query_tail ::= */ yytestcase(yyruleno==1806);
      /* (1809) table_offset_tail ::= */ yytestcase(yyruleno==1809);
      /* (1814) values_row_contents ::= */ yytestcase(yyruleno==1814);
      /* (1825) values_query_tail ::= */ yytestcase(yyruleno==1825);
      /* (1847) values_order_direction ::= */ yytestcase(yyruleno==1847);
